SELECT MAHH, TENHH, DONGIA, SLTON
FROM HANG_HOA
ORDER BY DONGIA DESC;

SELECT MAHH, TENHH, DONGIA
FROM HANG_HOA
WHERE MANHOM = 'TP';

SELECT MAHH, TENHH, DONGIA
FROM HANG_HOA
WHERE DONGIA > (SELECT AVG(DONGIA) FROM HANG_HOA);

SELECT DISTINCT MANHOM
FROM HANG_HOA
ORDER BY MANHOM;

SELECT MADL, TENDL, DIACHI
FROM DAI_LY
WHERE TENDL LIKE '%bách hóa%';

SELECT MAHTDG, THUNG
FROM HINH_THUC_DONG_GOI
WHERE LOC IS NULL;

SELECT MAHH, TENHH, DONGIA
FROM HANG_HOA
WHERE MANHOM IN ('BOT', 'TP');

SELECT MAHH, TENHH
FROM HANG_HOA
WHERE MAHH IN (SELECT DISTINCT MAHH FROM CTHD);

SELECT MAHH, TENHH
FROM HANG_HOA
WHERE MAHH NOT IN (SELECT DISTINCT MAHH FROM CTHD);

SELECT MADL, TENDL
FROM DAI_LY dl
WHERE EXISTS (SELECT 1 FROM HOA_DON WHERE MADL = dl.MADL);

SELECT MADL, TENDL
FROM DAI_LY dl
WHERE NOT EXISTS (SELECT 1 FROM HOA_DON WHERE MADL = dl.MADL);

SELECT MAHH, TENHH
FROM HANG_HOA
WHERE MAHH NOT IN (SELECT DISTINCT MAHH FROM CTPX);

SELECT h.MAHH, h.TENHH
FROM HANG_HOA h
WHERE h.MAHH IN (
  SELECT MAHH FROM CTPX GROUP BY MAHH
  HAVING SUM(SOLUONG) > (
    SELECT SUM(SLBAN) FROM CTHD WHERE MAHH = h.MAHH
  )
)
AND h.MAHH IN (SELECT MAHH FROM CTHD)
ORDER BY h.MAHH;
